PREFIX brick: <http://brickschema.org/brick#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT ?uri ?label WHERE {
  ?uri a brick:Zone .
  OPTIONAL { ?uri rdfs:label ?label }
  ORDER BY ?label
}

SELECT ?cls (COUNT(*) AS ?c) WHERE {
  ?uri a ?cls .
  FILTER strstarts(str(?cls), "brickschema.org")
} ORDER BY DESC(?c)

SELECT ?uri ?label WHERE {
  ?uri rdfs:label ?label .
  FILTER(str(?label) = "Core_mid" OR str(?label)="zone" OR contains(str(?label),"Zone"))
}

